// This code snippet demonstrates the use of jwt.decode() and jwt.verify() to highlight the difference in behavior
const jwt = require('jsonwebtoken');

const token = 'your.jwt.token.here';
const secretKey = 'your-secret-key';

// Using jwt.decode() (no signature verification)
const decodedWithoutVerify = jwt.decode(token, { complete: true });
console.log('Decoded without verification:', decodedWithoutVerify);

// Using jwt.verify() (signature verification)
try {
  const decodedWithVerify = jwt.verify(token, secretKey);
  console.log('Decoded with verification:', decodedWithVerify);
} catch (error) {
  console.log('Verification failed:', error.message);
}

